// Calculate the discounts
const subtotal = 68;
const shipping = 6;

// Step 1: Promo PROMO0F1B01 — 20% off, max \$50
const promoRaw = subtotal * 0.20;  // 13.60
const promoDiscount = Math.round(promoRaw); // \$14
console.log('=== STEP 1: PROMO CODE ===');
console.log('Subtotal:', subtotal);
console.log('20% of \$' + subtotal + ' = \$' + promoRaw);
console.log('Promo discount (rounded): \$' + promoDiscount);
console.log('Under max cap of \$50: ✓');

// Step 2: Remaining balance after promo
const afterPromo = subtotal - promoDiscount + shipping;
console.log('\n=== STEP 2: REMAINING BALANCE ===');
console.log('Subtotal - promo + shipping = \$' + subtotal + ' - \$' + promoDiscount + ' + \$' + shipping + ' = \$' + afterPromo);

// Step 3: Loyalty points — 100 pts = \$1, redeem all 7181
const totalPoints = 7181;
const maxLoyaltyDollars = Math.floor(totalPoints / 100); // \$71
console.log('\n=== STEP 3: LOYALTY POINTS ===');
console.log('Available: ' + totalPoints + ' points = \$' + maxLoyaltyDollars + ' max');
console.log('Remaining balance: \$' + afterPromo);
const loyaltyDiscount = Math.min(maxLoyaltyDollars, afterPromo);
const pointsUsed = loyaltyDiscount * 100;
const pointsRemaining = totalPoints - pointsUsed;
console.log('Loyalty discount applied: \$' + loyaltyDiscount);
console.log('Points redeemed: ' + pointsUsed);
console.log('Points remaining: ' + pointsRemaining);

// Step 4: Final total
const finalTotal = afterPromo - loyaltyDiscount;
console.log('\n=== FINAL TOTAL ===');
console.log('\$' + subtotal + ' (subtotal) - \$' + promoDiscount + ' (promo) - \$' + loyaltyDiscount + ' (loyalty) + \$' + shipping + ' (shipping) = \$' + finalTotal);
"

